to the latest version, the default).

=item * C<< $msg->read_offset() >> / C<< $msg->read_offset($value) >>

Type: C<Int64>

The offset for the first byte to return in the read, relative to the start
of the object.

A negative `read_offset` value will be interpreted as the number of bytes
back from the end of the object to be returned. For example, if an object's
length is 15 bytes, a GetObjectMediaRequest with `read_offset` = -5 and
`read_limit` = 3 would return bytes 10 through 12 of the object. Requesting
a negative offset whose magnitude is larger than the size of the object
will result in an error.

=item * C<< $msg->read_limit() >> / C<< $msg->read_limit($value) >>

Type: C<Int64>

The maximum number of `data` bytes the server is allowed to return in the
sum of all `Object` messages. A `read_limit` of zero indicates that there
is no limit, and a negative `read_limit` will cause an error.

If the stream returns fewer bytes than allowed by the `read_limit` and no
error occurred, the stream includes all data from the `read_offset` to the
end of the resource.

