=head2 Google::Storage::V1::Storage::InsertObjectRequest

Message for writing an object.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->upload_id() >> / C<< $msg->upload_id($value) >>

Type: C<String>

For resumable uploads. This should be the `upload_id` returned from a
call to `StartResumableWriteResponse`.

=item * C<< $msg->insert_object_spec() >> / C<< $msg->insert_object_spec($value) >>

Type: C<Message> (L<Google::Storage::V1::Storage::InsertObjectSpec>)

For non-resumable uploads. Describes the overall upload, including the
destination bucket and object name, preconditions, etc.

=item * C<< $msg->write_offset() >> / C<< $msg->write_offset($value) >>

Type: C<Int64>

Required. The offset from the beginning of the object at which the data should be
written.

In the first `InsertObjectRequest` of a `InsertObject()` action, it
indicates the initial offset for the `Insert()` call. The value B<must> be
equal to the `committed_size` that a call to `QueryWriteStatus()` would
return (0 if this is the first write to the object).

On subsequent calls, this value B<must> be no larger than the sum of the
first `write_offset` and the sizes of all `data` chunks sent previously on
this stream.

An incorrect value will cause an error.

=item * C<< $msg->checksummed_data() >> / C<< $msg->checksummed_data($value) >>

Type: C<Message> (L<Google::Storage::V1::StorageResources::ChecksummedData>)

The data to insert. If a crc32c checksum is provided that doesn't match
the checksum computed by the service, the request will fail.

=item * C<< $msg->reference() >> / C<< $msg->reference($value) >>

Type: C<Message> (L<Google::Storage::V1::Storage::GetObjectMediaRequest>)

A reference to an existing object. This can be used to support
several use cases:
  - Writing a sequence of data buffers supports the basic use case of
    uploading a complete object, chunk by chunk.
  - Writing a sequence of references to existing objects allows an
    object to be composed from a collection of objects, which can be
    used to support parallel object writes.
  - Writing a single reference with a given offset and size can be used
    to create an object from a slice of an existing object.
  - Writing an object referencing a object slice (created as noted
    above) followed by a data buffer followed by another object
    slice can be used to support delta upload functionality.

=item * C<< $msg->object_checksums() >> / C<< $msg->object_checksums($value) >>

Type: C<Message> (L<Google::Storage::V1::StorageResources::ObjectChecksums>)

Checksums for the complete object. If the checksums computed by the service
don't match the specifified checksums the call will fail. May only be
provided in the first or last request (either with first_message, or
finish_write set).

=item * C<< $msg->finish_write() >> / C<< $msg->finish_write($value) >>

Type: C<Bool>

If `true`, this indicates that the write is complete. Sending any
`InsertObjectRequest`s subsequent to one in which `finish_write` is `true`
will cause an error.
For a non-resumable write (where the upload_id was not set in the first
message), it is an error not to set this field in the final message of the
stream.

=item * C<< $msg->common_object_request_params() >> / C<< $msg->common_object_request_params($value) >>

Type: C<Message> (L<Google::Storage::V1::Storage::CommonObjectRequestParams>)

A set of parameters common to Storage API requests concerning an object.

=item * C<< $msg->common_request_params() >> / C<< $msg->common_request_params($value) >>

Type: C<Message> (L<Google::Storage::V1::Storage::CommonRequestParams>)

A set of parameters common to all Storage API requests.

=back

